from pathlib import Path
import base64, hashlib, json, subprocess, tempfile, zlib

ROOT = Path('portable/app_payload')
PATCH_SHA256 = '070d417fcce1a988c66291d0239005f5c0399dad18e7695e7c140cdc77874f07'
PATCH_ZLIB_B64 = ''''''
EXPECTED = {
    'capture_pool.py': '7b95931f5f2b2a9840d1bfaa921522cddfef53762c358b3aa1f2836226cce741',
    'evidence/main_farm_worker.json': '52385141eb70a955f401ee3decc698fea5d1ee72d914e0696f27f3a3fbc245ec',
    'maple_engine_v2.py': 'a1ed552e9e893dcd20b1c9b40e9cbca1cac20b7c427a9d997cf582c1f532b021',
    'maple_nghia_pro.py': '020770a55f5f59b4be1ce07c8de28eee15019070146b593c23ed3a1d56349ea4',
    'nghia_spotify_nologin.py': 'aa07672bddd4da5b2a40f8320b31db756844b3db3cb3a4e592927878a4390458',
    'spotify_all_cure_market.py': '734fa741f736a1998ec53aa8835bd3d51ce4002d60138cbb15a789ee0239000e',
    'spotify_recovered_core.py': '72e30e7c5518d31ae100195fc7f4297b9d031af47610a91f5cfc0ea2ab1c3609',
    'spotify_revive_state.py': '625fa9400713bbd8bb3db65087f2090c5303280508824d0d81a836ba702699fe',
    'spotify_watchdog.py': 'b78803f61f17598103e3090387fcb675bf2d1f45a8a9af4157fe7ceb1045c870',
    'spotify_worker_supervisor.py': '6c39c7b1b79c8364691d9776209c9b362718a1f06cf1cda535f01234af8b8bf2',
}

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

patch = zlib.decompress(base64.b64decode(PATCH_ZLIB_B64))
assert hashlib.sha256(patch).hexdigest() == PATCH_SHA256
with tempfile.NamedTemporaryFile('wb', delete=False, suffix='.patch') as fh:
    fh.write(patch)
    patch_path = Path(fh.name)
try:
    subprocess.run(['git','apply','--check','--directory=portable/app_payload',str(patch_path)],check=True)
    subprocess.run(['git','apply','--directory=portable/app_payload',str(patch_path)],check=True)
finally:
    patch_path.unlink(missing_ok=True)

for name, expected in EXPECTED.items():
    got=sha(ROOT/name)
    assert got==expected,(name,got,expected)
Path('portable/version.json').write_text(json.dumps({'version':'10.0.2'},indent=2)+'\n',encoding='utf-8')
ud=Path('portable/user_data'); ud.mkdir(parents=True,exist_ok=True)
(ud/'update_status.json').write_text(json.dumps({'latest_version':'10.0.2','local_version':'10.0.2','notes':'Nghia V10.0.2 Codex Canonical Stability','state':'up_to_date'},indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print('V1002_RUNTIME_PATCH_OK',len(EXPECTED))
